SubProceso EncontrarMayor(datos[] Como Entero Por Referencia, indice Como Entero, tamano Como Entero) Como Entero
    Si indice = tamano - 1 Entonces
        Retornar datos[indice];
    SiNo
        Definir restante Como Entero;
        restante <- EncontrarMayor(datos, indice + 1, tamano);
        Si datos[indice] > restante Entonces
            Retornar datos[indice];
        SiNo
            Retornar restante;
        FinSi
    FinSi
FinSubProceso

Proceso EjecutarMayorRecursivo
    Dimension numeros[5] Como Entero;
    Leer numeros[0];
    Leer numeros[1];
    Leer numeros[2];
    Leer numeros[3];
    Leer numeros[4];
    Escribir EncontrarMayor(numeros, 0, 5);
FinProceso
